129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
132	        HttpHeaders headers = new HttpHeaders();
133	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
134	        LocalDate effectiveDate = owner.getRegistrationDate() != null
135	            ? owner.getRegistrationDate() : LocalDate.now();
136	        LocalDate registrationDate = toBusinessDay(effectiveDate);
137	        owner.setRegistrationDate(registrationDate);
138	        long createdToday = this.clinicService.findAllOwners().stream()
139	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
140	            .count();
141	        if (createdToday >= 100) {
142	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
143	        }
144	        owner.setBulkSignupWarning(createdToday > 80);
145	        String address = normalizeAddress(owner.getAddress());
146	        if (address == null || address.isEmpty()) {
147	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
148	        }
149	        owner.setAddress(address);
150	        String telephone = toE164(owner.getTelephone());
151	        if (telephone == null) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        owner.setTelephone(telephone);
155	        if (owner.getEmail() != null) {
156	            String email = normalizeEmail(owner.getEmail());
157	            if (!EMAIL_PATTERN.matcher(email).matches()) {
158	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
159	            }
160	            owner.setEmail(email);
161	        }
162	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
163	            .anyMatch(existing -> telephone.equals(toE164(existing.getTelephone())));
164	        if (telephoneInUse) {
165	            return new ResponseEntity<>(HttpStatus.CONFLICT);
166	        }
167	        String cityKey = householdKey(owner.getCity());
168	        long cityCount = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> existing.getCity() != null
170	                && cityKey.equals(householdKey(existing.getCity())))
171	            .count();
172	        if (cityCount >= 50) {
173	            return new ResponseEntity<>(HttpStatus.CONFLICT);
174	        }
175	        String lastNameKey = householdKey(owner.getLastName());
176	        String addressKey = householdKey(owner.getAddress());
177	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
178	            .filter(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
179	                && addressKey.equals(householdKey(existing.getAddress())))
180	            .toList();
181	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
182	            String householdId = householdMembers.stream()
183	                .map(Owner::getHouseholdId)
184	                .filter(Objects::nonNull)
185	                .findFirst()
186	                .orElseGet(() -> householdId(owner));
187	            owner.setHouseholdId(householdId);
188	            for (Owner member : householdMembers) {
189	                if (member.getHouseholdId() == null) {
190	                    member.setHouseholdId(householdId);
191	                    this.clinicService.saveOwner(member);
192	                }
193	            }
194	        } else if (!householdMembers.isEmpty()) {
195	            return new ResponseEntity<>(HttpStatus.CONFLICT);
196	        }
197	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
198	        String firstNameKey = householdKey(owner.getFirstName());
199	        String namesakeLastNameKey = householdKey(owner.getLastName());
200	        long namesakeCount = this.clinicService.findAllOwners().stream()
201	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
202	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
203	            .count();
204	        owner.setNamesakeCount((int) namesakeCount);
205	        this.clinicService.saveOwner(owner);
206	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
207	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
208	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
209	        headers.setLocation(UriComponentsBuilder.newInstance()
210	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
211	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
212	    }
