214	    /**
215	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
216	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
217	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
218	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}.
219	     *
220	     * @param telephone the raw telephone value (may be {@code null})
221	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
222	     *         a valid E.164 number
223	     */
224	    private String toE164(String telephone) {
225	        if (telephone == null) {
226	            return null;
227	        }
228	        String trimmed = telephone.trim();
229	        boolean hasCountryCode = trimmed.startsWith("+");
230	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
231	        if (hasCountryCode) {
232	            cleaned = cleaned.substring(1);
233	        }
234	        if (!cleaned.matches("[0-9]+")) {
235	            return null;
236	        }
237	        String digits;
238	        if (hasCountryCode) {
239	            digits = cleaned;
240	        } else {
241	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
242	            digits = "61" + national;
243	        }
244	        if (digits.length() < 8 || digits.length() > 15) {
245	            return null;
246	        }
247	        return "+" + digits;
248	    }
249	
250	    /**
251	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
252	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
253	     *
254	     * @param email the raw email value (must not be {@code null})
255	     * @return the trimmed, lower-cased email
256	     */
257	    private String normalizeEmail(String email) {
258	        return email.trim().toLowerCase(Locale.ROOT);
259	    }
260	
261	    /**
262	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
263	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
264	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
265	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
266	     * normalized form, and every household comparison uses it.
267	     *
268	     * @param address the raw address value (may be {@code null})
269	     * @return the normalized address, or {@code null} if the input was {@code null}
270	     */
271	    private String normalizeAddress(String address) {
272	        if (address == null) {
273	            return null;
274	        }
275	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
276	        if (collapsed.isEmpty()) {
277	            return collapsed;
278	        }
279	        String[] tokens = collapsed.split(" ");
280	        StringBuilder sb = new StringBuilder(collapsed.length());
281	        for (int i = 0; i < tokens.length; i++) {
282	            if (i > 0) {
283	                sb.append(' ');
284	            }
285	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
286	        }
287	        return sb.toString();
288	    }
289	
290	    /**
291	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
292	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
293	     * so that owners are compared case-insensitively with collapsed whitespace.
294	     *
295	     * @param value the raw value (must not be {@code null})
296	     * @return the normalized comparison key
297	     */
298	    private String householdKey(String value) {
299	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
300	    }
301	
302	    /**
303	     * Derives a stable, shared household identifier for the owner's household. The value is a
304	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
305	     * every owner in the same household derives the identical identifier of the form
306	     * {@code 'HH-<12 upper-case hex>'}.
307	     *
308	     * @param owner the owner whose household identifier is derived
309	     * @return the stable household identifier
310	     */
311	    private String householdId(Owner owner) {
312	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
313	        try {
314	            byte[] digest = MessageDigest.getInstance("SHA-256")
315	                .digest(key.getBytes(StandardCharsets.UTF_8));
316	            StringBuilder sb = new StringBuilder(digest.length * 2);
317	            for (byte b : digest) {
318	                sb.append(String.format("%02x", b));
319	            }
320	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
321	        }
322	        catch (java.security.NoSuchAlgorithmException e) {
323	            throw new IllegalStateException("SHA-256 not available", e);
324	        }
325	    }
326	
327	    /**
328	     * Builds the customer code for a newly registered owner in the form
329	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three
330	     * letters of the city, {@code LAST3} the upper-cased first three letters of the last name
331	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
332	     * number of owners already registered in that city (e.g. {@code 'SYD-SMI-0007'}).
333	     *
334	     * @param city     the owner's city
335	     * @param lastName the owner's last name
336	     * @return the assigned customer code
337	     */
338	    private String nextCustomerCode(String city, String lastName) {
339	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
340	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
341	        String cityKey = householdKey(city);
342	        int sequence = (int) this.clinicService.findAllOwners().stream()
343	            .filter(existing -> existing.getCity() != null && cityKey.equals(householdKey(existing.getCity())))
344	            .count() + 1;
345	        return String.format(Locale.ROOT, "%s-%s-%04d", city3, last3, sequence);
346	    }
347	
348	    /**
349	     * Rolls a registration date forward onto a business day. When the given date falls on a
350	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
351	     *
352	     * @param date the effective registration date (must not be {@code null})
353	     * @return the same date if it is a weekday, otherwise the next Monday
354	     */
355	    private LocalDate toBusinessDay(LocalDate date) {
356	        DayOfWeek dayOfWeek = date.getDayOfWeek();
357	        if (dayOfWeek == DayOfWeek.SATURDAY) {
358	            return date.plusDays(2);
359	        }
360	        if (dayOfWeek == DayOfWeek.SUNDAY) {
361	            return date.plusDays(1);
362	        }
363	        return date;
364	    }
